/**
 * Shared types for the Quiz Me feature (page + components in src/components/quiz).
 */

// One multiple-choice question, as generated by the generate-quiz edge function.
// correctIndex is the position (0-3) of the right answer in `options`.
export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctIndex: number;
  hint: string;
  topic: string;
  difficulty: "easy" | "medium" | "hard";
}

// standard: untimed | time-crunch: 30s per question | exam-prep: easy -> hard order
export type QuizMode = "standard" | "time-crunch" | "exam-prep";

// Summary of a finished quiz, shown on the results screen and saved to quiz_results.
// userAnswers[i] is the chosen option for question i (null = unanswered / timed out).
// weakAreas = topics of the questions the user got wrong.
export interface QuizResult {
  score: number;
  total: number;
  timeTakenSeconds: number | null;
  wrongQuestions: QuizQuestion[];
  userAnswers: (number | null)[];
  weakAreas: string[];
  mode: QuizMode;
  course: string;
}
